const statuses=['Pending','In Transit','Out for Delivery','Delivered','Delayed','Cancelled'];const statusTransitions={'Pending':['In Transit','Delayed','Cancelled'],'In Transit':['Out for Delivery','Delayed','Delivered','Cancelled'],'Out for Delivery':['Delivered','Delayed','Cancelled'],'Delayed':['In Transit','Out for Delivery','Cancelled'],'Delivered':[],'Cancelled':[]};const priorities=['Low','Normal','High','Urgent'];const chartHours=Array.from({length:9},(_,i)=>`${String(i+8).padStart(2,'0')}:00`);
function readStore(key,fallback){try{const v=JSON.parse(localStorage.getItem(key));return Array.isArray(v)?v:fallback}catch{return fallback}}function saveStore(key,value){localStorage.setItem(key,JSON.stringify(value))}
function Status({value}){let cls=['Delivered','Available','On duty'].includes(value)?'good':['Delayed','Attention','Maintenance','Off duty'].includes(value)?'warn':['Out for Delivery','On route','In Transit'].includes(value)?'blue':'neutral';return <span className={`status ${cls}`}><i/>{value||'Unknown'}</span>}
function PageHeading({eyebrow,title,description,children}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="heading-actions">{children}</div></div>}
function Modal({title,onClose,children,wide=false}){useEffect(()=>{const fn=e=>e.key==='Escape'&&onClose();window.addEventListener('keydown',fn);return()=>window.removeEventListener('keydown',fn)},[onClose]);return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className={`modal ${wide?'modal-wide':''}`}><div className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={onClose} aria-label="Close"><X size={19}/></button></div>{children}</section></div>}
function Shell({children,user,onLogout,mode,notify}){const navigate=useNavigate();const[mobile,setMobile]=useState(false);const[notifications,setNotifications]=useState(false);const alertsEnabled=localStorage.getItem('ff_alerts')!=='false';const loc=useLocation();const titles={'/':'Operations overview','/shipments':'Shipments','/tracking':'Tracking & routes','/fleet':'Fleet management','/reports':'Reports & analytics','/drivers':'Team & drivers','/settings':'Workspace settings','/operations':'Operations centre'};const links=[['/','Overview',LayoutDashboard],['/shipments','Shipments',Package],['/tracking','Tracking & routes',MapPin],['/fleet','Fleet management',Truck]];const management=[['/reports','Reports & analytics',BarChart3],['/drivers','Team & drivers',Users],['/settings','Settings',Settings],['/operations','Operations centre',ClipboardList]];return <div className="app-shell"><aside className={`sidebar ${mobile?'sidebar-open':''}`}><div className="brand"><div className="brand-mark"><Command size={21}/></div><span>fleet<span className="brand-light">flow</span><small>LOGISTICS OS</small></span><button className="mobile-close" onClick={()=>setMobile(false)}><X size={18}/></button></div><div className="workspace workspace-button" aria-label="Current workspace"><div className="workspace-avatar">N</div><div><b>Aravali Logistics</b><small>{mode==='demo'?'Local demo workspace':'Connected workspace'}</small></div><ChevronDown size={15}/></div><div className="nav-label">WORKSPACE</div><nav>{links.map(([to,label,Icon])=><NavLink end={to==='/'} key={to} to={to} onClick={()=>setMobile(false)} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span></NavLink>)}</nav><div className="nav-label management-label">MANAGEMENT</div><nav>{management.filter(([to])=>to!=='/operations'||mode==='api').map(([to,label,Icon])=><NavLink key={to} to={to} onClick={()=>setMobile(false)} className={({isActive})=>`nav-link ${isActive?'active':''}`}><Icon size={18}/><span>{label}</span></NavLink>)}</nav><div className="sidebar-bottom"><div className="support-card"><div className="support-icon"><CircleHelpFallback/></div><b>Need a hand?</b><p>Find your way around the operations workspace.</p><button onClick={()=>notify('Tip: use the left menu to open each module. Forms and row actions are interactive.')}>Quick help <ArrowRight size={14}/></button></div><div className="user-row"><div className="user-avatar">{(user?.name||'A').slice(0,1).toUpperCase()}</div><div className="user-info"><b>{user?.name||'Operations Admin'}</b><small>{mode==='demo'?'Demo administrator':user?.role||'Operator'}</small></div><button className="icon-button" title="Sign out" onClick={onLogout}><LogOut size={17}/></button></div></div></aside><main className="main"><header className="topbar"><button className="mobile-menu icon-button" onClick={()=>setMobile(true)}><Menu/></button><div className="crumb"><span>Workspace</span><span className="slash">/</span><b>{titles[loc.pathname]||'Operations overview'}</b></div><div className="top-actions"><span className={`mode-chip ${mode==='demo'?'demo-chip':''}`}>{mode==='demo'?'LOCAL DEMO':'API CONNECTED'}</span><button className="icon-button notification-button" title="Notifications" onClick={()=>mode==='api'?navigate('/operations?tab=notifications'):setNotifications(v=>!v)}><Bell size={17}/>{alertsEnabled&&<i/>}</button><span className="top-divider"/><button className="date-button" onClick={()=>notify(new Date().toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))}><CalendarDays size={15}/>{new Date().toLocaleDateString('en-IN',{month:'short',day:'numeric',timeZone:'Asia/Kolkata'})}<ChevronDown size={14}/></button><div className="top-avatar">{(user?.name||'A').slice(0,1).toUpperCase()}</div></div></header>{notifications&&<div className="notification-pop"><b>Workspace notifications</b><p><AlertTriangle size={14}/> Check delayed shipments and vehicles with low fuel.</p><button className="text-action" onClick={()=>{setNotifications(false);notify('Notifications reviewed')}}>Mark as reviewed</button></div>}<div className="page-content">{children}<footer>© 2026 FleetFlow <span>Built for the people who keep goods moving.</span><span className="footer-right"><ShieldCheck size={13}/> {mode==='demo'?'Demo data only':'Authenticated session'}</span></footer></div></main></div>}
function CircleHelpFallback(){return <Activity size={18}/>}
function Metric({label,value,change,positive=true,icon:Icon,accent,sub,onClick}){const Tag=onClick?'button':'div';return <Tag className={`metric-card ${onClick?'metric-interactive':''}`} onClick={onClick} title={onClick?`Open ${label}`:undefined} role={onClick?'button':undefined} tabIndex={onClick?0:undefined} onKeyDown={onClick?(e)=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();onClick()}}:undefined}><div className="metric-top"><span>{label}</span><span className={`metric-icon ${accent}`}><Icon size={18}/></span></div><div className="metric-value">{value}</div><div className="metric-bottom"><span className={positive?'trend-up':'trend-down'}>{positive?<ArrowUpRight size={14}/>:<ArrowDownRight size={14}/>} {change}</span><span>{sub}</span></div></Tag>}
function Dashboard({shipments,vehicles,onNavigate}){const active=shipments.filter(s=>!['Delivered','Cancelled'].includes(s.status)).length;const delivered=shipments.filter(s=>s.status==='Delivered').length;const delayed=shipments.filter(s=>s.status==='Delayed').length;const available=vehicles.filter(v=>v.status==='Available').length;const rate=shipments.length?Math.round(delivered/shipments.length*1000)/10:0;const chart=useMemo(()=>statuses.map(status=>({status,count:shipments.filter(s=>s.status===status).length})).filter(x=>x.count),[shipments]);const activity=useMemo(()=>chartHours.map(time=>({time,loads:shipments.reduce((n,s)=>n+(s.events||[]).filter(ev=>{const d=new Date(ev.occurredAt);return Number.isFinite(d.getTime())&&`${String(d.getHours()).padStart(2,'0')}:00`===time}).length,0)})),[shipments]);return <><PageHeading eyebrow={new Date().toLocaleDateString('en-IN',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase()} title="Operations overview" description="A clear view of today's shipments, fleet and delivery exceptions."><button className="btn btn-ghost" onClick={()=>downloadCSV('fleetflow-shipments.csv',shipments)}><Download size={16}/> Export data</button><button className="btn btn-primary" onClick={()=>onNavigate('/shipments?new=1')}><Plus size={17}/> New shipment</button></PageHeading><div className="welcome-strip"><div className="welcome-symbol"><Zap size={19}/></div><div><b>{delayed?`${delayed} shipment${delayed>1?'s':''} need attention`:'Your operations at a glance'}</b><span>{delayed?'Review delays and update customers with the latest ETA.':'Review current loads, fleet availability and delivery progress.'}</span></div><button onClick={()=>onNavigate('/tracking')}>Open tracking <ArrowRight size={15}/></button><div className="strip-decoration"/></div><div className="section-head"><div><h2>Network at a glance</h2><p>Calculated from the shipments and vehicles in this workspace</p></div><span className="updated"><i/> Workspace records</span></div><div className="metrics-grid"><Metric label="Active shipments" value={active} change={`${shipments.length} total`} icon={Package} accent="mint" sub="current records" onClick={()=>onNavigate('/shipments')}/><Metric label="Delivery completion" value={`${rate}%`} change={`${delivered} delivered`} icon={CheckCircle2} accent="blue" sub="of current shipments" onClick={()=>onNavigate('/reports')}/><Metric label="Fleet availability" value={`${available}/${vehicles.length}`} change={`${vehicles.length-available} assigned / other`} icon={Truck} accent="violet" sub="registered vehicles" onClick={()=>onNavigate('/fleet')}/><Metric label="Delayed loads" value={delayed} change={delayed?'Needs review':'All clear'} positive={!delayed} icon={Clock3} accent="amber" sub="exception queue" onClick={()=>onNavigate('/shipments?status=Delayed')}/></div><div className="dashboard-grid"><section className="panel performance-panel"><div className="panel-head"><div><h3>Shipment activity</h3><p>Shipment events by hour from available records</p></div><button className="select-small" onClick={()=>onNavigate('/reports')}>View reports <ArrowRight size={13}/></button></div><div className="chart-legend"><i/> Recorded events <span>Based on shipment history</span></div><div className="chart-area"><ResponsiveContainer width="100%" height="100%"><AreaChart data={activity} margin={{top:10,right:4,left:-25,bottom:0}}><defs><linearGradient id="mintFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#6ee7b7" stopOpacity={.24}/><stop offset="95%" stopColor="#6ee7b7" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#253149"/><XAxis dataKey="time" axisLine={false} tickLine={false} tick={{fill:'#75819d',fontSize:11}} dy={9}/><Tooltip contentStyle={{background:'#11182b',border:'1px solid #2b3854',borderRadius:10,color:'#fff'}}/><Area type="monotone" dataKey="loads" name="Loads" stroke="#6ee7b7" strokeWidth={2.5} fill="url(#mintFill)"/></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span><b>{shipments.length}</b> shipments in workspace</span><span><i className="legend-dot"/> Status chart updates with records</span></div></section><section className="panel fleet-panel"><div className="panel-head"><div><h3>Fleet status</h3><p>Registered vehicle availability</p></div><button className="text-action" onClick={()=>onNavigate('/fleet')}>View fleet <ArrowRight size={14}/></button></div><div className="fleet-summary"><div className="donut"><div><b>{vehicles.length}</b><small>vehicles</small></div></div><div className="fleet-legend"><div><i className="dot mint-dot"/><span>On route</span><b>{vehicles.filter(v=>v.status==='On route').length}</b></div><div><i className="dot blue-dot"/><span>Available</span><b>{available}</b></div><div><i className="dot amber-dot"/><span>Attention</span><b>{vehicles.filter(v=>['Attention','Maintenance','Offline'].includes(v.status)).length}</b></div></div></div><div className="fleet-note"><span className="note-icon"><Fuel size={15}/></span><div><b>{vehicles.filter(v=>Number(v.fuel)<35).length} vehicle(s) low on fuel</b><small>Fuel below 35% needs a check</small></div><ArrowRight size={16} className="note-arrow"/></div></section></div><section className="panel shipments-panel"><div className="panel-head"><div><h3>Recent shipments</h3><p>Open any shipment to inspect its details and history</p></div><button className="text-action" onClick={()=>onNavigate('/shipments')}>All shipments <ArrowRight size={14}/></button></div><ShipmentTable shipments={shipments.slice(0,5)} onSelect={s=>onNavigate(`/shipments?view=${s._id}`)}/></section><section className="panel quick-links"><div className="panel-head"><div><h3>Quick actions</h3><p>Jump straight into common tasks</p></div></div><div className="quick-link-grid"><button onClick={()=>onNavigate('/shipments?new=1')}><Plus/><b>Create a shipment</b><small>Record a new load</small></button><button onClick={()=>onNavigate('/fleet?new=1')}><Truck/><b>Add a vehicle</b><small>Update the fleet register</small></button><button onClick={()=>onNavigate('/drivers?new=1')}><UserRound/><b>Add a driver</b><small>Manage driver details</small></button><button onClick={()=>onNavigate('/reports')}><FileText/><b>Build a report</b><small>Export workspace data</small></button></div></section></>}
function ShipmentTable({shipments,onSelect}){return <div className="table-wrap"><table><thead><tr><th>SHIPMENT ID</th><th>CUSTOMER / ROUTE</th><th>STATUS</th><th>PRIORITY</th><th>ETA</th><th>PROGRESS</th><th>DETAILS</th></tr></thead><tbody>{shipments.map(s=><tr key={s._id} onClick={()=>onSelect?.(s)} className={onSelect?'clickable-row':''}><td><b className="tracking-id">{s.trackingNumber}</b><small className="sub-cell">{s.vehicle||'Unassigned'}</small></td><td><b>{s.customer}</b><small className="sub-cell route-cell">{s.origin} <ArrowRight size={11}/> {s.destination}</small></td><td><Status value={s.status}/></td><td><span className={`priority ${String(s.priority).toLowerCase()}`}><i/>{s.priority}</span></td><td className="eta-cell">{formatEta(s.eta)}</td><td><div className="progress-cell"><div className="progress-track"><span style={{width:`${s.progress??0}%`}}/></div><small>{s.progress??0}%</small></div></td><td><button className="icon-button row-more" title="View details" onClick={e=>{e.stopPropagation();onSelect?.(s)}}><Eye size={16}/></button></td></tr>)}</tbody></table>{shipments.length===0&&<div className="empty-state"><Package size={25}/><b>No shipments found</b><span>Try changing the search or create a new shipment.</span></div>}</div>}
function formatEta(value){if(!value)return'Not set';if(String(value).startsWith('Delivered'))return value;const d=new Date(value);return Number.isNaN(d.getTime())?value:d.toLocaleString('en-IN',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'})}
function downloadCSV(filename,rows){const safe=rows.map(row=>Object.fromEntries(Object.entries(row).filter(([k])=>!['_id','events','__v'].includes(k))));const keys=[...new Set(safe.flatMap(r=>Object.keys(r)))];const csv=[keys.join(','),...safe.map(r=>keys.map(k=>`"${String(r[k]??'').replaceAll('"','""')}"`).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));a.download=filename;a.click();URL.revokeObjectURL(a.href)}
function Shipments({shipments,setShipments,vehicles,drivers,notify,mode,location}){const navigate=useNavigate();const params=new URLSearchParams(location.search);const[query,setQuery]=useState('');const[status,setStatus]=useState(params.get('status')||'All statuses');const[priority,setPriority]=useState('All priorities');const[modal,setModal]=useState(false);const[detail,setDetail]=useState(null);const[edit,setEdit]=useState(null);const[form,setForm]=useState({customer:'',origin:'',destination:'',priority:'Normal',vehicle:'',driver:'',eta:'',status:'Pending'});const[trackForm,setTrackForm]=useState({status:'In Transit',location:'',note:''});const filtered=shipments.filter(s=>`${s.trackingNumber} ${s.customer} ${s.origin} ${s.destination} ${s.driver||''}`.toLowerCase().includes(query.toLowerCase())&&(status==='All statuses'||s.status===status)&&(priority==='All priorities'||s.priority===priority));useEffect(()=>{if(params.get('new')==='1'){setEdit(null);setForm({customer:'',origin:'',destination:'',priority:'Normal',vehicle:'',driver:'',eta:'',status:'Pending'});setModal(true)}if(params.get('view')){const s=shipments.find(x=>x._id===params.get('view'));if(s)setDetail(s)}},[location.search,shipments]);const reset=()=>{setModal(false);setEdit(null);if(params.has('new')||params.has('view'))navigate('/shipments',{replace:true})};const submit=async e=>{e.preventDefault();const payload={...form,progress:form.status==='Delivered'?100:form.status==='Out for Delivery'?90:form.status==='In Transit'?35:0,events:edit?.events||[]};try{if(mode==='api'){if(edit){const r=await api.patch(`/shipments/${edit._id}`,payload);payload._id=edit._id;Object.assign(payload,r.data.shipment)}else{const r=await api.post('/shipments',payload);Object.assign(payload,r.data.shipment)}}else{payload._id=edit?edit._id:`local-${Date.now()}`;payload.trackingNumber=edit?.trackingNumber||`FF-${String(Date.now()).slice(-6)}`;payload.events=payload.events||[]}setShipments(prev=>edit?prev.map(x=>x._id===edit._id?{...x,...payload}:x):[payload,...prev]);if(mode==='demo')saveStore('ff_india_shipments_v1',edit?shipments.map(x=>x._id===edit._id?{...x,...payload}:x):[payload,...shipments]);notify(edit?'Shipment details saved':'Shipment created');reset()}catch(err){notify(getError(err))}};const updateStatus=async e=>{e.preventDefault();const updated={...detail,status:trackForm.status,progress:trackForm.status==='Delivered'?100:trackForm.status==='Out for Delivery'?90:trackForm.status==='In Transit'?Math.max(detail.progress||0,35):detail.progress||0,events:[...(detail.events||[]),{...trackForm,occurredAt:new Date().toISOString()}]};try{if(mode==='api'){const response=await api.post(`/shipments/${detail._id}/events`,trackForm);Object.assign(updated,response.data.shipment||{});}setShipments(prev=>prev.map(s=>s._id===detail._id?updated:s));if(mode==='demo')saveStore('ff_india_shipments_v1',shipments.map(s=>s._id===detail._id?updated:s));setDetail(updated);notify('Tracking event added')}catch(err){notify(getError(err))}};const remove=async s=>{if(!window.confirm(`Cancel shipment ${s.trackingNumber}?`))return;const updated={...s,status:'Cancelled'};try{if(mode==='api')await api.patch(`/shipments/${s._id}`,{status:'Cancelled'});setShipments(prev=>prev.map(x=>x._id===s._id?updated:x));if(mode==='demo')saveStore('ff_india_shipments_v1',shipments.map(x=>x._id===s._id?updated:x));setDetail(updated);notify('Shipment cancelled')}catch(err){notify(getError(err))}};return <><PageHeading eyebrow="OPERATIONS / CONSIGNMENTS" title="Shipments" description="Create loads, assign a vehicle and keep every delivery update in one place."><button className="btn btn-ghost" onClick={()=>downloadCSV('fleetflow-shipments.csv',filtered)}><Download size={16}/> Export CSV</button><button className="btn btn-primary" onClick={()=>{setEdit(null);setForm({customer:'',origin:'',destination:'',priority:'Normal',vehicle:'',driver:'',eta:'',status:'Pending'});setModal(true)}}><Plus size={17}/> New shipment</button></PageHeading><div className="panel list-panel"><div className="list-toolbar"><div className="search-box"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search ID, customer, route or driver"/></div><div className="filter-row"><label><Filter size={14}/><select value={status} onChange={e=>setStatus(e.target.value)}><option>All statuses</option>{statuses.map(x=><option key={x}>{x}</option>)}</select></label><label><SlidersHorizontal size={14}/><select value={priority} onChange={e=>setPriority(e.target.value)}><option>All priorities</option>{priorities.map(x=><option key={x}>{x}</option>)}</select></label><button className="btn btn-ghost" onClick={()=>{setQuery('');setStatus('All statuses');setPriority('All priorities')}}><RefreshCw size={14}/> Reset</button></div></div><div className="list-summary"><span><b>{filtered.length}</b> shipments shown</span><span>Click a row to open full details</span></div><ShipmentTable shipments={filtered} onSelect={s=>setDetail(s)}/></div>{modal&&<Modal title={edit?'Edit shipment':'Create a shipment'} onClose={reset}><form className="form-grid" onSubmit={submit}><label>Customer / account<input required maxLength="120" value={form.customer} onChange={e=>setForm({...form,customer:e.target.value})} placeholder="e.g. Aravali Agro Foods"/></label><label>Origin<input required value={form.origin} onChange={e=>setForm({...form,origin:e.target.value})} placeholder="City, state or warehouse (India)"/></label><label>Destination<input required value={form.destination} onChange={e=>setForm({...form,destination:e.target.value})} placeholder="City, state or warehouse (India)"/></label><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}>{priorities.map(x=><option key={x}>{x}</option>)}</select></label><label>Vehicle registration<select value={form.vehicle} onChange={e=>setForm({...form,vehicle:e.target.value})}><option value="">Unassigned</option>{vehicles.filter(v=>(!edit||v.registration===edit.vehicle||!(['Maintenance','Offline'].includes(v.status)))&&(!form.driver||!v.driver||v.driver===form.driver)).map(v=><option key={v._id} value={v.registration}>{v.registration} · {v.type} · {v.status}</option>)}</select></label><label>Driver<select value={form.driver} onChange={e=>setForm({...form,driver:e.target.value})}><option value="">Unassigned</option>{drivers.filter(d=>(!edit||d.name===edit.driver||!(['Off duty','On leave'].includes(d.status)))&&(!form.vehicle||!d.vehicle||d.vehicle===form.vehicle)).map(d=><option key={d._id} value={d.name}>{d.name} · {d.status}</option>)}</select></label><label>Estimated delivery<input type="datetime-local" value={form.eta} onChange={e=>setForm({...form,eta:e.target.value})}/></label><label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{statuses.filter(s=>edit?(s===form.status||statusTransitions[edit.status]?.includes(s)):s!=='Cancelled').map(x=><option key={x}>{x}</option>)}</select></label><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={reset}>Cancel</button><button type="submit" className="btn btn-primary"><Save size={16}/>{edit?'Save changes':'Create shipment'}</button></div></form></Modal>}{detail&&<Modal title={`Shipment ${detail.trackingNumber}`} onClose={()=>setDetail(null)} wide><div className="detail-summary"><div><span>Customer</span><b>{detail.customer}</b></div><div><span>Status</span><Status value={detail.status}/></div><div><span>Priority</span><b>{detail.priority}</b></div><div><span>Progress</span><b>{detail.progress||0}%</b></div></div><div className="route-banner"><div><MapPin/><small>ORIGIN</small><b>{detail.origin}</b></div><ArrowRight/><div><MapPin/><small>DESTINATION</small><b>{detail.destination}</b></div></div><div className="detail-columns"><section><h3>Shipment information</h3><p><span>Assigned vehicle</span><b>{detail.vehicle||'Not assigned'}</b></p><p><span>Driver</span><b>{detail.driver||'Not assigned'}</b></p><p><span>Estimated delivery</span><b>{formatEta(detail.eta)}</b></p><div className="detail-actions"><button className="btn btn-ghost" onClick={()=>{setForm({customer:detail.customer,origin:detail.origin,destination:detail.destination,priority:detail.priority,vehicle:detail.vehicle||'',driver:detail.driver||'',eta:detail.eta||'',status:detail.status});setEdit(detail);setDetail(null);setModal(true)}}><Edit3 size={15}/> Edit details</button><button className="btn btn-ghost" onClick={()=>{const link=`${window.location.origin}/track/${encodeURIComponent(detail.trackingNumber)}`;navigator.clipboard?.writeText(link).then(()=>notify('Customer tracking link copied')).catch(()=>notify(link));}}><FileText size={15}/> Copy customer link</button><button className="btn btn-danger" onClick={()=>remove(detail)}><Trash2 size={15}/> Cancel load</button></div></section><section><h3>Tracking history</h3><form className="event-form" onSubmit={updateStatus}><label>New status<select value={trackForm.status} onChange={e=>setTrackForm({...trackForm,status:e.target.value})}>{statuses.map(x=><option key={x}>{x}</option>)}</select></label><label>Current location<input value={trackForm.location} onChange={e=>setTrackForm({...trackForm,location:e.target.value})} placeholder="Warehouse, city or highway (India)"/></label><label>Update note<input value={trackForm.note} onChange={e=>setTrackForm({...trackForm,note:e.target.value})} placeholder="What changed?"/></label><button className="btn btn-primary" type="submit"><Plus size={15}/> Add update</button></form><div className="timeline">{[...(detail.events||[])].reverse().map((ev,i)=><div className="timeline-event" key={i}><i/><div><b>{ev.status}</b><small>{ev.location||'Location not provided'} · {new Date(ev.occurredAt||Date.now()).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})}</small>{ev.note&&<p>{ev.note}</p>}</div></div>)}{!detail.events?.length&&<p className="muted">No tracking updates yet. Add the first update above.</p>}</div></section></div></Modal>}</>}
function Fleet({vehicles,setVehicles,drivers,notify,mode,location}){const[search,setSearch]=useState('');const[show,setShow]=useState(false);const[edit,setEdit]=useState(null);const[detail,setDetail]=useState(null);const[form,setForm]=useState({registration:'',type:'Heavy truck',driver:'',capacity:'',status:'Available',location:'Depot',fuel:100});const filtered=vehicles.filter(v=>`${v.registration} ${v.driver||''} ${v.type} ${v.location||''}`.toLowerCase().includes(search.toLowerCase()));useEffect(()=>{if(new URLSearchParams(location.search).get('new')==='1')setShow(true)},[location.search]);const save=async e=>{e.preventDefault();const p={...form,fuel:Number(form.fuel)};try{if(mode==='api'){if(edit)await api.patch(`/vehicles/${edit._id}`,p);else{const r=await api.post('/vehicles',p);p._id=r.data.vehicle._id}}else p._id=edit?edit._id:`local-v-${Date.now()}`;const next=edit?vehicles.map(v=>v._id===edit._id?{...v,...p}:v):[p,...vehicles];setVehicles(next);if(mode==='demo')saveStore('ff_india_vehicles_v1',next);setShow(false);setEdit(null);notify(edit?'Vehicle updated':'Vehicle registered')}catch(err){notify(getError(err))}};const archiveVehicle=async v=>{if(!window.confirm(`Archive vehicle ${v.registration}?`))return;try{if(mode==='api')await api.delete(`/vehicles/${v._id}`);const next=vehicles.filter(x=>x._id!==v._id);setVehicles(next);if(mode==='demo')saveStore('ff_india_vehicles_v1',next);setDetail(null);notify('Vehicle archived')}catch(err){notify(getError(err))}};const startEdit=v=>{setEdit(v);setForm({registration:v.registration,type:v.type,driver:v.driver||'',capacity:v.capacity,status:v.status,location:v.location||'',fuel:v.fuel??100});setDetail(null);setShow(true)};return <><PageHeading eyebrow="OPERATIONS / FLEET" title="Fleet management" description="Manage registered vehicles, assignments, fuel and availability."><button className="btn btn-ghost" onClick={()=>downloadCSV('fleetflow-fleet.csv',filtered)}><Download size={16}/> Export CSV</button><button className="btn btn-primary" onClick={()=>{setEdit(null);setForm({registration:'',type:'Heavy truck',driver:'',capacity:'',status:'Available',location:'Depot',fuel:100});setShow(true)}}><Plus size={17}/> Add vehicle</button></PageHeading><div className="metrics-grid compact-metrics"><Metric label="Registered vehicles" value={vehicles.length} change="Fleet register" icon={Truck} accent="mint" sub="all records"/><Metric label="Available" value={vehicles.filter(v=>v.status==='Available').length} change="Ready to assign" icon={CheckCircle2} accent="blue" sub="current status"/><Metric label="Low fuel" value={vehicles.filter(v=>Number(v.fuel)<35).length} change="Below 35%" positive={!vehicles.some(v=>Number(v.fuel)<35)} icon={Fuel} accent="amber" sub="needs attention"/><Metric label="Maintenance" value={vehicles.filter(v=>v.status==='Maintenance').length} change="Out of service" icon={Settings} accent="violet" sub="current status"/></div><section className="panel list-panel"><div className="panel-head"><div><h3>Vehicle directory</h3><p>Click a vehicle card to inspect or edit it</p></div><div className="search-box fleet-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search registration, driver..."/></div></div><div className="vehicle-grid">{filtered.map(v=><article className="vehicle-card vehicle-clickable" key={v._id} onClick={()=>setDetail(v)}><div className="vehicle-card-top"><div className="vehicle-illustration"><Truck size={25}/></div><Status value={v.status}/><button className="icon-button" title="Edit vehicle" onClick={e=>{e.stopPropagation();startEdit(v)}}><Ellipsis size={18}/></button></div><h3>{v.registration}</h3><p>{v.type}</p><div className="vehicle-divider"/><div className="vehicle-info"><div><span>Assigned driver</span><b>{v.driver||'Unassigned'}</b></div><div><span>Load capacity</span><b>{v.capacity||'Not specified'}</b></div></div><div className="fuel-label"><span>Fuel level</span><b>{v.fuel??'—'}{v.fuel!=null?'%':''}</b></div><div className="fuel-track"><span style={{width:`${v.fuel??0}%`,background:(v.fuel??100)<35?'#fbbf24':'#6ee7b7'}}/></div><div className="vehicle-location"><MapPin size={14}/>{v.location||'Location unavailable'}</div><div className="vehicle-card-hint">Click to view details <ArrowRight size={13}/></div></article>)}</div>{!filtered.length&&<div className="empty-state"><Truck/><b>No vehicles match</b><span>Change the search or register a vehicle.</span></div>}</section>{show&&<Modal title={edit?'Edit vehicle':'Register vehicle'} onClose={()=>{setShow(false);setEdit(null)}}><form className="form-grid" onSubmit={save}><label>Registration ID<input required value={form.registration} onChange={e=>setForm({...form,registration:e.target.value.toUpperCase()})} placeholder="RJ14-GA-4821"/></label><label>Vehicle type<select value={form.type} onChange={e=>setForm({...form,type:e.target.value})}>{['Heavy truck','LCV','Container truck','Refrigerated truck','Pickup','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Assigned driver<select value={form.driver} onChange={e=>setForm({...form,driver:e.target.value})}><option value="">Unassigned</option>{drivers.filter(d=>(!edit||d.name===edit.driver||!(['Off duty','On leave'].includes(d.status)))&&(!d.vehicle||d.vehicle===edit?.registration)).map(d=><option key={d._id} value={d.name}>{d.name} · {d.status}</option>)}</select></label><label>Load capacity<input required value={form.capacity} onChange={e=>setForm({...form,capacity:e.target.value})} placeholder="e.g. 16 MT"/></label><label>Status<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['Available','On route','Attention','Maintenance','Offline'].map(x=><option key={x}>{x}</option>)}</select></label><label>Current location<input value={form.location} onChange={e=>setForm({...form,location:e.target.value})} placeholder="Warehouse, city or highway in India"/></label><label>Fuel level (%)<input type="number" min="0" max="100" required value={form.fuel} onChange={e=>setForm({...form,fuel:e.target.value})}/></label><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={()=>setShow(false)}>Cancel</button><button type="submit" className="btn btn-primary"><Save size={16}/>{edit?'Save vehicle':'Register vehicle'}</button></div></form></Modal>}{detail&&<Modal title={detail.registration} onClose={()=>setDetail(null)}><div className="detail-summary"><div><span>Vehicle type</span><b>{detail.type}</b></div><div><span>Status</span><Status value={detail.status}/></div><div><span>Fuel</span><b>{detail.fuel}%</b></div><div><span>Capacity</span><b>{detail.capacity}</b></div></div><div className="detail-columns"><section><h3>Vehicle details</h3><p><span>Driver</span><b>{detail.driver||'Unassigned'}</b></p><p><span>Location</span><b>{detail.location||'Not provided'}</b></p><p><span>Registration</span><b>{detail.registration}</b></p><button className="btn btn-primary" onClick={()=>startEdit(detail)}><Edit3 size={15}/> Edit vehicle</button> <button className="btn btn-danger" onClick={()=>archiveVehicle(detail)}><Trash2 size={15}/> Archive vehicle</button></section></div></Modal>}</>}
function Tracking({shipments,onSelect,mode}){const[query,setQuery]=useState('');const[filter,setFilter]=useState('Active');const[positions,setPositions]=useState([]);const[gpsError,setGpsError]=useState('');const[gpsUpdated,setGpsUpdated]=useState(null);const items=shipments.filter(s=>`${s.trackingNumber} ${s.origin} ${s.destination} ${s.customer}`.toLowerCase().includes(query.toLowerCase())&&(filter==='All'||(filter==='Active'&&!['Delivered','Cancelled'].includes(s.status))||s.status===filter));useEffect(()=>{if(mode!=='api'){setPositions([]);return}let active=true;const load=async()=>{try{const r=await api.get('/telemetry/locations/latest');if(!active)return;setPositions(r.data.items||[]);setGpsError('');setGpsUpdated(new Date())}catch(e){if(active)setGpsError(getError(e))}};load();const timer=setInterval(load,30000);return()=>{active=false;clearInterval(timer)}},[mode]);const gpsAge=d=>{const mins=Math.max(0,Math.floor((Date.now()-new Date(d).getTime())/60000));return mins<1?'Just now':mins<60?`${mins} min ago`:`${Math.floor(mins/60)} hr ago`};return <><PageHeading eyebrow="LOGISTICS / CONTROL TOWER" title="Shipment tracking" description="Find a load, inspect its latest status and review its tracking history."><button className="btn btn-ghost" onClick={()=>onSelect(items[0])} disabled={!items.length}><Eye size={15}/> Open first result</button></PageHeading><div className="tracking-layout"><section className="panel map-panel"><div className="panel-head"><div><h3>Vehicle GPS positions</h3><p>{mode==='api'?'Live device positions · refreshes every 30 seconds':'GPS positions appear after connecting the API and a Traccar device'}</p></div><span className={`mode-chip ${positions.length?'':'demo-chip'}`}>{mode==='api'?(positions.length?`${positions.length} GPS FIXES`:'GPS WAITING'):'DEMO MODE'}</span></div>{mode==='api'?<>{gpsError&&<div className="empty-state">GPS data could not be loaded: {gpsError}</div>}{!gpsError&&!positions.length&&<div className="empty-state"><MapPin/><b>No GPS positions received yet</b><span>Connect Traccar, assign its device ID to a vehicle and wait for the first valid position.</span></div>}<div className="tracking-items">{positions.map(point=><div className="tracking-item" key={`${point.vehicle}-${point._id||point.recordedAt}`}><span className="tracking-item-icon"><Truck size={18}/></span><span className="tracking-item-main"><b>{point.vehicle}</b><small>{Number(point.latitude).toFixed(5)}, {Number(point.longitude).toFixed(5)} · {Number(point.speedKph||0).toFixed(1)} km/h</small><small>Heading {Math.round(point.heading||0)}° · {gpsAge(point.recordedAt)}</small></span><a className="btn btn-ghost" href={`https://www.openstreetmap.org/?mlat=${encodeURIComponent(point.latitude)}&mlon=${encodeURIComponent(point.longitude)}#map=15/${encodeURIComponent(point.latitude)}/${encodeURIComponent(point.longitude)}`} target="_blank" rel="noreferrer">Open map ↗</a></div>)}</div><p className="map-attribution">{gpsUpdated?`Last API refresh: ${gpsUpdated.toLocaleTimeString('en-IN')}`:'Waiting for GPS API'} · Map data © OpenStreetMap contributors</p></>:<div className="map-canvas"><div className="map-grid"/><svg className="route-svg" viewBox="0 0 700 400" preserveAspectRatio="none"><path d="M80 280 C160 250 180 100 290 150 S440 310 520 210 S610 90 650 100"/><path d="M40 80 C180 100 220 260 330 250 S490 80 630 310"/><path d="M110 340 C220 330 310 80 430 130 S550 260 660 240"/></svg>{[[12,70,'Mumbai hub'],[42,40,'Jaipur hub'],[72,30,'Delhi NCR'],[82,72,'Kolkata hub'],[54,68,'Indore hub']].map(([x,y,name],i)=><button key={name} className={`map-pin pin-${i%3}`} style={{left:`${x}%`,top:`${y}%`}} title={name}><span/><label>{name}</label></button>)}<div className="map-watermark">FLEETFLOW <span>ROUTE VIEW</span></div><div className="map-attribution">Illustrative map only · Live positions require a connected GPS device</div></div>}<div className="map-stats"><div><span className="map-stat-icon mint"><Truck size={17}/></span><div><b>{shipments.filter(s=>!['Delivered','Cancelled'].includes(s.status)).length}</b><small>Active loads</small></div></div><div><span className="map-stat-icon blue"><MapPin size={17}/></span><div><b>{positions.length||new Set(shipments.map(s=>`${s.origin}-${s.destination}`)).size}</b><small>{mode==='api'?'GPS fixes':'Distinct sample routes'}</small></div></div><div><span className="map-stat-icon amber"><Clock3 size={17}/></span><div><b>{shipments.filter(s=>s.status==='Delayed').length}</b><small>Delayed loads</small></div></div></div></section><section className="panel tracking-list"><div className="panel-head"><div><h3>Shipment lookup</h3><p>Choose a shipment to open its full history</p></div><span className="count-pill">{items.length} results</span></div><div className="search-box tracking-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Tracking ID, route or customer..."/></div><div className="tracking-filter">{['Active','All',...statuses.filter(s=>s==='Delayed'||s==='Delivered')].map(f=><button key={f} className={filter===f?'selected':''} onClick={()=>setFilter(f)}>{f}</button>)}</div><div className="tracking-items">{items.map(s=><button className="tracking-item" key={s._id} onClick={()=>onSelect(s)}><span className="tracking-item-icon"><Truck size={18}/></span><span className="tracking-item-main"><b>{s.trackingNumber}</b><small>{s.origin} → {s.destination}</small><span className="progress-track"><span style={{width:`${s.progress||0}%`}}/></span></span><span className="tracking-item-meta"><Status value={s.status}/><small>{formatEta(s.eta)}</small></span></button>)}{!items.length&&<div className="empty-state">No shipments found.</div>}</div></section></div></>}
function Drivers({drivers,setDrivers,vehicles,notify,mode,location}){const[query,setQuery]=useState('');const[show,setShow]=useState(false);const[edit,setEdit]=useState(null);const[detail,setDetail]=useState(null);const[form,setForm]=useState({name:'',phone:'',email:'',license:'',status:'Available',vehicle:''});useEffect(()=>{if(new URLSearchParams(location.search).get('new')==='1')setShow(true)},[location.search]);const filtered=drivers.filter(d=>`${d.name} ${d.email} ${d.license} ${d.vehicle}`.toLowerCase().includes(query.toLowerCase()));const archiveDriver=async d=>{if(!window.confirm(`Archive driver ${d.name}?`))return;try{if(mode==='api')await api.delete(`/drivers/${d._id}`);const next=drivers.filter(x=>x._id!==d._id);setDrivers(next);if(mode==='demo')saveStore('ff_india_drivers_v1',next);setDetail(null);notify('Driver archived')}catch(err){notify(getError(err))}};const save=async e=>{e.preventDefault();const p={...form};try{if(mode==='api'){if(edit){const r=await api.patch(`/drivers/${edit._id}`,p);Object.assign(p,r.data.driver)}else{const r=await api.post('/drivers',p);Object.assign(p,r.data.driver)}}const next=edit?drivers.map(d=>d._id===edit._id?{...d,...p}:d):[{...p,_id:p._id||`local-d-${Date.now()}`},...drivers];setDrivers(next);if(mode==='demo')saveStore('ff_india_drivers_v1',next);setShow(false);setEdit(null);notify(edit?'Driver details saved':'Driver added to team')}catch(err){notify(getError(err))}};return <><PageHeading eyebrow="PEOPLE / DRIVER DIRECTORY" title="Team & drivers" description="Keep driver contact details, licences, availability and vehicle assignments up to date."><button className="btn btn-ghost" onClick={()=>downloadCSV('fleetflow-drivers.csv',filtered)}><Download size={16}/> Export CSV</button><button className="btn btn-primary" onClick={()=>{setEdit(null);setForm({name:'',phone:'',email:'',license:'',status:'Available',vehicle:''});setShow(true)}}><Plus size={17}/> Add driver</button></PageHeading><div className="panel list-panel"><div className="panel-head"><div><h3>Driver directory</h3><p>{drivers.length} people in the workspace</p></div><div className="search-box fleet-search"><Search size={16}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search name, email, licence..."/></div></div><div className="driver-grid">{filtered.map(d=><article className="driver-card" key={d._id} onClick={()=>setDetail(d)}><div className="driver-card-head"><div className="driver-avatar"><UserRound/></div><button className="icon-button" onClick={e=>{e.stopPropagation();setEdit(d);setForm(d);setShow(true)}} title="Edit driver"><Edit3 size={16}/></button></div><h3>{d.name}</h3><Status value={d.status}/><div className="driver-contact"><span><Phone size={14}/>{d.phone||'No phone added'}</span><span><Mail size={14}/>{d.email||'No email added'}</span></div><div className="vehicle-location"><Truck size={14}/>{d.vehicle||'No vehicle assigned'}</div><button className="text-action" onClick={e=>{e.stopPropagation();setDetail(d)}}>View profile <ArrowRight size={14}/></button></article>)}</div>{!filtered.length&&<div className="empty-state"><Users/><b>No matching drivers</b><span>Add a driver or try another search.</span></div>}</div>{show&&<Modal title={edit?'Edit driver':'Add a driver'} onClose={()=>{setShow(false);setEdit(null)}}><form className="form-grid" onSubmit={save}><label>Full name<input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Driver full name"/></label><label>Phone number<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})} placeholder="+91 98765 41000"/></label><label>Work email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})} placeholder="driver@example.in"/></label><label>Licence number<input required value={form.license} onChange={e=>setForm({...form,license:e.target.value})} placeholder="RJ1420160012345"/></label><label>Availability<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}>{['Available','On duty','Off duty','On leave'].map(x=><option key={x}>{x}</option>)}</select></label><label>Assigned vehicle<select value={form.vehicle} onChange={e=>setForm({...form,vehicle:e.target.value})}><option value="">Unassigned</option>{vehicles.filter(v=>!v.driver||v.registration===form.vehicle).map(v=><option key={v._id} value={v.registration}>{v.registration}</option>)}</select></label><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={()=>setShow(false)}>Cancel</button><button className="btn btn-primary"><Save size={16}/>Save driver</button></div></form></Modal>}{detail&&<Modal title={detail.name} onClose={()=>setDetail(null)}><div className="detail-summary"><div><span>Status</span><Status value={detail.status}/></div><div><span>Vehicle</span><b>{detail.vehicle||'Unassigned'}</b></div></div><div className="detail-columns"><section><h3>Contact details</h3><p><span>Phone</span><b>{detail.phone||'Not provided'}</b></p><p><span>Email</span><b>{detail.email||'Not provided'}</b></p><p><span>Licence</span><b>{detail.license||'Not provided'}</b></p><button className="btn btn-primary" onClick={()=>{setEdit(detail);setForm(detail);setDetail(null);setShow(true)}}><Edit3 size={15}/> Edit profile</button> <button className="btn btn-danger" onClick={()=>archiveDriver(detail)}><Trash2 size={15}/> Archive driver</button></section></div></Modal>}</>}
function Reports({shipments,vehicles,drivers,notify}){const[period,setPeriod]=useState('all');const[report,setReport]=useState('shipments');const filtered=period==='all'?shipments:shipments.filter(s=>{const d=new Date(s.createdAt||s.events?.[0]?.occurredAt||Date.now());const days=period==='7d'?7:30;const age=Date.now()-d.getTime();return Number.isFinite(age)&&age>=0&&age<days*86400000});const delivered=filtered.filter(s=>s.status==='Delivered').length;const delayed=filtered.filter(s=>s.status==='Delayed').length;const data=statuses.map(status=>({status,count:filtered.filter(s=>s.status===status).length}));const exportData=()=>{const rows=report==='shipments'?filtered:report==='vehicles'?vehicles:drivers;downloadCSV(`fleetflow-${report}-${new Date().toISOString().slice(0,10)}.csv`,rows);notify(`${rows.length} ${report} records exported`)};return <><PageHeading eyebrow="INSIGHTS / REPORTING" title="Reports & analytics" description="Review current operations and export records for follow-up or presentations."><button className="btn btn-primary" onClick={exportData}><Download size={16}/> Export selected report</button></PageHeading><div className="report-controls panel"><label>Report type<select value={report} onChange={e=>setReport(e.target.value)}><option value="shipments">Shipment register</option><option value="vehicles">Fleet register</option><option value="drivers">Driver directory</option></select></label><label>Date window<select value={period} onChange={e=>setPeriod(e.target.value)}><option value="all">All available records</option><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option></select></label><button className="btn btn-ghost" onClick={()=>{setPeriod('all');setReport('shipments')}}><RefreshCw size={15}/> Reset report</button></div><div className="metrics-grid"><Metric label="Records in report" value={report==='shipments'?filtered.length:report==='vehicles'?vehicles.length:drivers.length} change="Current selection" icon={ClipboardList} accent="mint" sub="export-ready"/><Metric label="Delivered shipments" value={delivered} change="Shipment status" icon={CheckCircle2} accent="blue" sub="selected window"/><Metric label="Delayed shipments" value={delayed} change={delayed?'Needs attention':'No delays recorded'} positive={!delayed} icon={Clock3} accent="amber" sub="selected window"/><Metric label="Fleet records" value={vehicles.length} change={`${drivers.length} driver profiles`} icon={Truck} accent="violet" sub="workspace totals"/></div><div className="dashboard-grid"><section className="panel performance-panel"><div className="panel-head"><div><h3>Shipment status breakdown</h3><p>Computed from the current shipment list</p></div></div><div className="report-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={data}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#253149"/><XAxis dataKey="status" tick={{fill:'#aab5ca',fontSize:10}} axisLine={false} tickLine={false}/><YAxis allowDecimals={false} tick={{fill:'#aab5ca',fontSize:11}} axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#11182b',border:'1px solid #2b3854',borderRadius:10,color:'#fff'}}/><Bar dataKey="count" name="Shipments" fill="#6ee7b7" radius={[5,5,0,0]}/></BarChart></ResponsiveContainer></div></section><section className="panel report-notes"><div className="panel-head"><div><h3>Report notes</h3><p>Read before sharing externally</p></div></div><div className="note-line"><CheckCircle2/><div><b>Exports include visible workspace records</b><p>CSV is generated in your browser from the current data.</p></div></div><div className="note-line"><AlertTriangle/><div><b>Sample data may be illustrative</b><p>In local demo mode, the starter records are examples, not actual freight activity.</p></div></div><div className="note-line"><ShieldCheck/><div><b>Check privacy before sharing</b><p>Remove customer or driver details if the recipient should not see them.</p></div></div></section></div></>}
function SettingsPage({user,mode,notify,onLogout}){const[workspace,setWorkspace]=useState(()=>localStorage.getItem('ff_workspace')||'Aravali Logistics');const[contact,setContact]=useState(()=>localStorage.getItem('ff_contact')||'operations@aravalilogistics.in');const[alerts,setAlerts]=useState(()=>localStorage.getItem('ff_alerts')!=='false');const[compact,setCompact]=useState(()=>localStorage.getItem('ff_compact')==='true');const[confirm,setConfirm]=useState(false);useEffect(()=>{document.body.classList.toggle('compact-tables',compact);return()=>document.body.classList.remove('compact-tables')},[compact]);const save=()=>{localStorage.setItem('ff_workspace',workspace);localStorage.setItem('ff_contact',contact);localStorage.setItem('ff_alerts',String(alerts));localStorage.setItem('ff_compact',String(compact));notify('Workspace preferences saved on this browser')};return <><PageHeading eyebrow="WORKSPACE / PREFERENCES" title="Settings" description="Manage workspace details and your local interface preferences."><button className="btn btn-primary" onClick={save}><Save size={16}/> Save settings</button></PageHeading><div className="settings-grid">{mode==='api'&&<PasswordSecurity notify={notify}/>}<section className="panel settings-panel"><div className="panel-head"><div><h3>Workspace details</h3><p>Basic information shown around the app</p></div><Settings/></div><label>Workspace name<input value={workspace} onChange={e=>setWorkspace(e.target.value)} maxLength="100"/></label><label>Operations contact email<input type="email" value={contact} onChange={e=>setContact(e.target.value)}/></label><div className="settings-readonly"><span>Current access mode</span><b>{mode==='demo'?'Local demo · saved in this browser':'API-backed session'}</b><small>{mode==='demo'?'Demo changes are stored in local browser storage.':'Operational records are managed through the connected API.'}</small></div></section><section className="panel settings-panel"><div className="panel-head"><div><h3>Interface preferences</h3><p>These preferences are stored locally</p></div><SlidersHorizontal/></div><label className="setting-toggle"><span><b>Show notification reminders</b><small>Display a reminder badge in the top bar</small></span><input type="checkbox" checked={alerts} onChange={e=>setAlerts(e.target.checked)}/></label><label className="setting-toggle"><span><b>Compact table layout</b><small>Preference saved; compact styling can be extended later</small></span><input type="checkbox" checked={compact} onChange={e=>setCompact(e.target.checked)}/></label><div className="settings-readonly"><span>Signed in as</span><b>{user?.name||'Operations user'}</b><small>{user?.email||'Local demo account'} · {user?.role||'demo administrator'}</small></div></section><section className="panel settings-panel settings-danger"><div className="panel-head"><div><h3>Session</h3><p>Leave the current workspace</p></div><ShieldCheck/></div><p className="muted">Signing out removes the current local session. In demo mode, the sample workspace records remain in this browser.</p><button className="btn btn-danger" onClick={()=>setConfirm(true)}><LogOut size={16}/> Sign out</button></section></div>{confirm&&<Modal title="Sign out of FleetFlow?" onClose={()=>setConfirm(false)}><p className="muted">You can sign in again or reopen the local demo workspace later.</p><div className="modal-actions"><button className="btn btn-ghost" onClick={()=>setConfirm(false)}>Stay here</button><button className="btn btn-danger" onClick={onLogout}>Sign out</button></div></Modal>}</>}

function CustomerPortal({user,mode,notify,onLogout}){
 const [items,setItems]=useState([]),[loading,setLoading]=useState(mode==='api'),[showRequest,setShowRequest]=useState(false),[form,setForm]=useState({customer:user?.name||'',origin:'',destination:'',priority:'Normal',eta:''}),[busy,setBusy]=useState(false);
 const demoItems=[{_id:'demo-c1',trackingNumber:'FF-DEMO-9001',customer:user?.name||'Demo Customer',origin:'Jaipur, Rajasthan',destination:'Gurugram, Haryana',status:'In Transit',priority:'Normal',eta:'Today, 6:30 PM',progress:64,events:[{status:'In Transit',location:'NH-48',note:'Moving towards destination',occurredAt:new Date().toISOString()}]},{_id:'demo-c2',trackingNumber:'FF-DEMO-9002',customer:user?.name||'Demo Customer',origin:'Ahmedabad, Gujarat',destination:'Jaipur, Rajasthan',status:'Delivered',priority:'Normal',eta:'Delivered',progress:100,events:[{status:'Delivered',location:'Jaipur',note:'Delivered successfully',occurredAt:new Date().toISOString()}]}];
 const load=async()=>{if(mode==='demo'){setItems(demoItems);setLoading(false);return}try{const r=await api.get('/shipments');setItems(r.data.shipments||[])}catch(e){notify(getError(e))}finally{setLoading(false)}};
 useEffect(()=>{load()},[]);
 const submit=async e=>{e.preventDefault();setBusy(true);try{if(mode==='demo'){setItems(v=>[{...form,_id:'demo-'+Date.now(),trackingNumber:'FF-DEMO-'+String(Date.now()).slice(-5),status:'Pending',progress:0,events:[{status:'Pending',location:form.origin,note:'Demo request submitted',occurredAt:new Date().toISOString()}]},...v])}else{await api.post('/shipments/customer-request',form);await load()}setShowRequest(false);notify('Shipment request submitted successfully')}catch(e){notify(getError(e))}finally{setBusy(false)}};
 const active=items.filter(x=>!['Delivered','Cancelled'].includes(x.status)).length,delivered=items.filter(x=>x.status==='Delivered').length;
 return <div className="customer-portal"><header className="customer-top"><div className="brand"><div className="brand-mark"><Command size={20}/></div><b>fleet<span>flow</span></b><span className="customer-label">CUSTOMER PORTAL</span></div><div className="customer-account"><span>{user?.name||'Customer'}</span><button className="btn btn-ghost" onClick={onLogout}><LogOut size={15}/> Sign out</button></div></header><main className="customer-main"><div className="page-heading"><div><span className="eyebrow">CUSTOMER WORKSPACE</span><h1>Welcome, {user?.name?.split(' ')[0]||'Customer'}</h1><p>Track your consignments and manage shipment requests.</p></div><button className="btn btn-primary" onClick={()=>setShowRequest(true)}><Plus size={16}/> Request a shipment</button></div><div className="customer-metrics"><div className="metric"><small>Active shipments</small><strong>{active}</strong><span>Currently moving / pending</span></div><div className="metric"><small>Delivered</small><strong>{delivered}</strong><span>Successfully completed</span></div><div className="metric"><small>Total shipments</small><strong>{items.length}</strong><span>Your account records</span></div></div><section className="panel customer-shipments"><div className="panel-head"><div><h2>Your shipments</h2><p>Only consignments associated with your account are shown.</p></div><button className="btn btn-ghost" onClick={load}><RefreshCw size={15}/> Refresh</button></div>{loading?<div className="empty">Loading your shipments…</div>:items.length===0?<div className="empty">No shipments yet. Submit a shipment request to get started.</div>:<div className="customer-list">{items.map(s=><article className="customer-shipment" key={s._id}><div className="customer-shipment-head"><div><b>{s.trackingNumber}</b><small>{s.customer}</small></div><span className={`status ${s.status==='Delayed'?'warn':s.status==='Delivered'?'':'blue'}`}>{s.status}</span></div><div className="customer-route"><div><small>PICKUP</small><b>{s.origin}</b></div><ArrowRight size={18}/><div><small>DELIVERY</small><b>{s.destination}</b></div></div><div className="customer-progress"><div className="track"><span style={{width:`${s.progress||0}%`}}/></div><span>{s.progress||0}%</span></div><div className="customer-event"><b>Latest update</b><span>{s.events?.at(-1)?.note||s.status}</span><small>{s.events?.at(-1)?.location||'Location pending'} · {s.eta||'ETA pending'}</small></div><div className="customer-track-link"><a href={`/track/${encodeURIComponent(s.trackingNumber)}`} target="_blank" rel="noreferrer">Open tracking details <ArrowUpRight size={14}/></a></div></article>)}</div>}</section><p className="customer-footnote"><ShieldCheck size={15}/> Your account can request and track shipments. Fleet, driver, billing and internal operations are managed by FleetFlow staff.</p></main>{showRequest&&<div className="modal-backdrop"><form className="modal customer-request-modal" onSubmit={submit}><div className="modal-head"><div><h2>Request a shipment</h2><p>FleetFlow operations will review and assign the vehicle and driver.</p></div><button type="button" className="icon-btn" onClick={()=>setShowRequest(false)}><X/></button></div><label className="field">Customer / business name<input required maxLength="120" value={form.customer} onChange={e=>setForm({...form,customer:e.target.value})}/></label><label className="field">Pickup address<input required minLength="5" maxLength="180" value={form.origin} onChange={e=>setForm({...form,origin:e.target.value})} placeholder="Area, city, state"/></label><label className="field">Delivery address<input required minLength="5" maxLength="180" value={form.destination} onChange={e=>setForm({...form,destination:e.target.value})} placeholder="Area, city, state"/></label><label className="field">Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option>Low</option><option>Normal</option><option>High</option></select></label><label className="field">Preferred delivery date / time<input value={form.eta} onChange={e=>setForm({...form,eta:e.target.value})} placeholder="e.g. 2 Nov, before 5 PM"/></label><div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={()=>setShowRequest(false)}>Cancel</button><button className="btn btn-primary" disabled={busy}>{busy?'Submitting…':'Submit request'}</button></div></form></div>}</div>
}

function Login({onLogin}){
 const [view,setView]=useState('login'),[email,setEmail]=useState('admin@fleetflow.demo'),[password,setPassword]=useState('FleetFlowDemo!2026'),[name,setName]=useState(''),[accountType,setAccountType]=useState('business'),[phone,setPhone]=useState(''),[companyName,setCompanyName]=useState(''),[gstin,setGstin]=useState(''),[address,setAddress]=useState(''),[purpose,setPurpose]=useState(''),[token,setToken]=useState(''),[newPassword,setNewPassword]=useState(''),[loading,setLoading]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');
 useEffect(()=>{const params=new URLSearchParams(window.location.search);const verify=params.get('verify'),reset=params.get('reset'),mail=params.get('email');if(mail)setEmail(mail);if(verify){setToken(verify);setView('verify')}else if(reset){setToken(reset);setView('reset')}},[]);
 const resetMessages=()=>{setError('');setMessage('')};
 const run=async(e)=>{e.preventDefault();setLoading(true);resetMessages();try{
  if(view==='login'){const r=await api.post('/auth/login',{email,password});localStorage.setItem('fleetflow_token',r.data.token);localStorage.setItem('fleetflow_user',JSON.stringify(r.data.user));onLogin(r.data.user,'api');return}
  if(view==='register'){const r=await api.post('/auth/register',{name,email,password,accountType,phone,companyName,gstin,address,purpose});setMessage(r.data.message);if(r.data.devVerificationToken){setToken(r.data.devVerificationToken);setView('verify')}else setView('login');return}
  if(view==='forgot'){const r=await api.post('/auth/forgot-password',{email});setMessage(r.data.message);if(r.data.devResetToken)setToken(r.data.devResetToken);setView('reset');return}
  if(view==='reset'){const r=await api.post('/auth/reset-password',{email,token,newPassword});setMessage(r.data.message);setView('login');setPassword('');return}
  if(view==='verify'){const r=await api.post('/auth/verify-email',{email,token});setMessage(r.data.message);setView('login');return}
 }catch(err){setError(err.response?getError(err):'Could not reach the API. Start the backend and MongoDB, then try again.')}finally{setLoading(false)}};
 const title={login:'Sign in to FleetFlow',register:'Create your account',forgot:'Reset your password',reset:'Choose a new password',verify:'Verify your email'}[view];
 return <div className="login-screen"><div className="login-art"><div className="login-brand"><div className="brand-mark"><Command size={22}/></div>fleet<span>flow</span></div><div className="login-copy"><span className="eyebrow">LOGISTICS OPERATIONS PLATFORM</span><h1>Move goods.<br/><span>Move business.</span></h1><p>One secure workspace for shipment visibility, fleet operations and customer delivery updates.</p><div className="login-stat-row"><div><b>Secure access</b><small>Role-based permissions</small></div><div><b>Shipment visibility</b><small>Event-based tracking</small></div><div><b>Operations</b><small>One control tower</small></div></div></div><div className="login-orbit orbit-one"/><div className="login-orbit orbit-two"/><div className="login-footer">FLEETFLOW · BUILT FOR INDIAN LOGISTICS</div></div><div className="login-form-side"><form className="login-form" onSubmit={run}><div className="mobile-login-brand"><div className="brand-mark"><Command size={20}/></div>fleetflow</div><span className="eyebrow">{view==='login'?'WELCOME BACK':'ACCOUNT ACCESS'}</span><h2>{title}</h2><p>{view==='register'?'Tell us how you plan to use FleetFlow. Your customer account is reviewed by an administrator.':view==='login'?'Sign in with your approved workspace credentials.':view==='forgot'?'Enter your account email. If it exists, reset instructions will be issued.':'Complete the secure account recovery step.'}</p>
 {error&&<div className="login-error">{error}</div>}{message&&<div className="login-security">{message}</div>}
 {view==='register'&&<><label>Full name<input required minLength="2" maxLength="80" value={name} onChange={e=>setName(e.target.value)} placeholder="Your full name"/></label><label>How will you use FleetFlow?<select value={accountType} onChange={e=>setAccountType(e.target.value)}><option value="business">Business / shipper</option><option value="individual">Individual customer</option><option value="transporter">Transporter / fleet owner</option><option value="driver">Driver</option><option value="other">Other</option></select></label></>}
 <label>Work email<div className="login-input"><Mail size={17}/><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@company.com"/></div></label>
 {['login','register'].includes(view)&&<label>Password<div className="login-input"><ShieldCheck size={17}/><input type="password" required minLength={view==='register'?12:8} maxLength="128" value={password} onChange={e=>setPassword(e.target.value)} placeholder={view==='register'?'At least 12 characters':'Your password'}/></div>{view==='register'&&<small className="demo-disclaimer">Use at least 12 characters. Never reuse a password.</small>}</label>}
 {view==='register'&&<><label>Mobile number<input required minLength="8" maxLength="20" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="+91 98XXXXXXXX"/></label>{accountType==='business'&&<><label>Company name<input required value={companyName} onChange={e=>setCompanyName(e.target.value)} maxLength="120" placeholder="Registered business name"/></label><label>GSTIN (if applicable)<input value={gstin} onChange={e=>setGstin(e.target.value.toUpperCase())} maxLength="15" placeholder="15-character GSTIN"/></label></>}<label>Business / pickup address<textarea required value={address} onChange={e=>setAddress(e.target.value)} maxLength="300" placeholder="Full address, city, state and PIN code"/></label><label>What do you need FleetFlow for?<textarea required minLength="5" maxLength="500" value={purpose} onChange={e=>setPurpose(e.target.value)} placeholder="e.g. Book shipments, track consignments, manage fleet..."/></label></>}
 {view==='reset'&&<><label>One-time reset token<input required value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste reset token"/></label><label>New password<input type="password" required minLength="12" maxLength="128" value={newPassword} onChange={e=>setNewPassword(e.target.value)} placeholder="At least 12 characters"/></label></>}
 {view==='verify'&&<label>Email verification token<input required value={token} onChange={e=>setToken(e.target.value)} placeholder="Paste verification token"/></label>}
 {view!=='login'&&view!=='register'&&view!=='reset'&&view!=='verify'&&null}
 <button className="btn btn-primary login-submit" disabled={loading}>{loading?'Please wait...':({login:'Sign in',register:'Submit account request',forgot:'Continue',reset:'Reset password',verify:'Verify email'}[view])}<ArrowRight size={17}/></button>
 {view==='login'&&<div className="auth-links"><button type="button" onClick={()=>{resetMessages();setView('forgot')}}>Forgot password?</button><button type="button" onClick={()=>{resetMessages();setView('register')}}>Create customer account</button></div>}
 {view!=='login'&&<div className="auth-links"><button type="button" onClick={()=>{resetMessages();setView('login')}}>Back to sign in</button></div>}
 {view==='login'&&<><div className="login-security"><ShieldCheck size={15}/> Protected API sign-in · Role-based access</div><div className="login-divider"><span>PORTFOLIO DEMO</span></div><button type="button" className="btn btn-ghost login-submit" onClick={()=>{const user={name:'FleetFlow Demo',email:'demo@fleetflow.local',role:'demo administrator'};localStorage.removeItem('fleetflow_token');localStorage.setItem('fleetflow_user',JSON.stringify(user));onLogin(user,'demo')}}><ShieldCheck size={16}/> Explore admin dashboard</button><button type="button" className="btn btn-ghost login-submit" onClick={()=>{const user={name:'Demo Customer',email:'customer@fleetflow.demo',role:'customer',accountType:'business',onboardingStatus:'approved'};localStorage.removeItem('fleetflow_token');localStorage.setItem('fleetflow_user',JSON.stringify(user));onLogin(user,'demo')}}><Users size={16}/> Explore customer dashboard</button><small className="demo-disclaimer">Demo data stays in this browser and is not connected to the backend.</small></>}
 </form></div></div>
}
export default function App(){const[session,setSession]=useState(()=>{try{const user=JSON.parse(localStorage.getItem('fleetflow_user'));return user?{user,mode:localStorage.getItem('fleetflow_mode')|| (localStorage.getItem('fleetflow_token')?'api':'demo')}:null}catch{return null}});const[shipments,setShipments]=useState(()=>readStore('ff_india_shipments_v1',initialShipments));const[vehicles,setVehicles]=useState(()=>readStore('ff_india_vehicles_v1',initialVehicles));const[drivers,setDrivers]=useState(()=>readStore('ff_india_drivers_v1',initialDrivers));const[toast,setToast]=useState('');const navigate=useNavigate();const location=useLocation();const notify=m=>{setToast(m);window.setTimeout(()=>setToast(''),3500)};useEffect(()=>{if(session?.mode==='demo')saveStore('ff_india_shipments_v1',shipments)},[shipments,session?.mode]);useEffect(()=>{if(session?.mode==='demo')saveStore('ff_india_vehicles_v1',vehicles)},[vehicles,session?.mode]);useEffect(()=>{if(session?.mode==='demo')saveStore('ff_india_drivers_v1',drivers)},[drivers,session?.mode]);useEffect(()=>{const onUnauthorized=()=>{setSession(null);navigate('/')};window.addEventListener('fleetflow:unauthorized',onUnauthorized);return()=>window.removeEventListener('fleetflow:unauthorized',onUnauthorized)},[navigate]);useEffect(()=>{if(session?.mode!=='api')return;let active=true;setShipments([]);setVehicles([]);setDrivers([]);Promise.allSettled(session.user?.role==='customer'?[api.get('/shipments')]:[api.get('/shipments'),api.get('/vehicles'),api.get('/drivers')]).then(results=>{if(!active)return;const [s,v,d]=results;if(s.status==='fulfilled')setShipments(s.value.data.shipments||s.value.data);else notify(`Shipments could not load: ${getError(s.reason)}`);if(session.user?.role!=='customer'){if(v?.status==='fulfilled')setVehicles(v.value.data.vehicles||v.value.data);else if(v)notify(`Fleet could not load: ${getError(v.reason)}`);if(d?.status==='fulfilled')setDrivers(d.value.data.drivers||d.value.data);else if(d)notify(`Drivers could not load: ${getError(d.reason)}`)}});return()=>{active=false}},[session?.mode]);const login=(user,mode)=>{localStorage.setItem('fleetflow_user',JSON.stringify(user));localStorage.setItem('fleetflow_mode',mode);setSession({user,mode})};const logout=()=>{localStorage.removeItem('fleetflow_token');localStorage.removeItem('fleetflow_user');localStorage.removeItem('fleetflow_mode');setSession(null);navigate('/')};if(location.pathname.startsWith('/track/'))return <Routes><Route path="/track/:trackingNumber" element={<PublicTracking/>}/></Routes>;if(!session)return <Login onLogin={login}/>;const mode=session.mode;if(session.user?.role==='customer')return <><CustomerPortal user={session.user} mode={mode} notify={notify} onLogout={logout}/>{toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}</>;return <><Shell user={session.user} mode={mode} onLogout={logout} notify={notify}><Routes><Route path="/" element={<Dashboard shipments={shipments} vehicles={vehicles} onNavigate={navigate}/>}/><Route path="/shipments" element={<Shipments shipments={shipments} setShipments={setShipments} vehicles={vehicles} drivers={drivers} notify={notify} mode={mode} location={location}/>}/><Route path="/fleet" element={<Fleet vehicles={vehicles} setVehicles={setVehicles} drivers={drivers} notify={notify} mode={mode} location={location}/>}/><Route path="/tracking" element={<Tracking shipments={shipments} mode={mode} onSelect={s=>{if(s)navigate(`/shipments?view=${s._id}`)}}/>}/><Route path="/reports" element={<Reports shipments={shipments} vehicles={vehicles} drivers={drivers} notify={notify}/>}/><Route path="/drivers" element={<Drivers drivers={drivers} setDrivers={setDrivers} vehicles={vehicles} notify={notify} mode={mode} location={location}/>}/><Route path="/settings" element={<SettingsPage user={session.user} mode={mode} notify={notify} onLogout={logout}/>}/><Route path="/operations" element={<Operations notify={notify} user={session.user} mode={mode}/>}/><Route path="*" element={<Dashboard shipments={shipments} vehicles={vehicles} onNavigate={navigate}/>}/></Routes></Shell>{toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}<button onClick={()=>setToast('')}><X size={15}/></button></div>}</>}
